 async function runBulkApplications(){
  const ids=[...selectedApps];if(!ids.length)return toast('Select at least one application.',1);
  if(ids.length>25)return toast('For safety, select no more than 25 applications per batch.',1);
  const action=$('#bulkAction').value;if(!action)return toast('Choose an action.',1);
  const batch=ids.map(id=>D.apps.find(a=>a.id===id)).filter(Boolean);
  if(action==='delete'&&batch.some(a=>a.admission_decision==='approved'))return toast('Remove admitted students from selection. They are protected.',1);
  const verb={approved:'admit',rejected:'reject',letter:'generate admission document for',results:'issue published result statement for',transcript:'issue published transcript for',delete:'permanently delete'}[action];
  if(!confirm(`You are about to ${verb} ${batch.length} application(s). Confirm your selection.`))return;
  let note=null;
  if(action==='rejected'||action==='delete'){
   note=await askNote('Reason for '+verb,'Give a reason to record in the audit history','Continue');
   if(!note||(action==='delete'&&note.length<10))return toast('A written reason of at least 10 characters is required for deletion.',1);
  }
  if(action==='delete'&&prompt('To confirm irreversible bulk deletion, type DELETE '+batch.length) !== 'DELETE '+batch.length)return toast('Confirmation cancelled.',1);
  const button=$('#runBulk');button.disabled=true;button.textContent='Processing…';let ok=0;const failures=[];
  if(action==='transcript'||action==='results'){
   const rr=await sb.rpc(action==='results'?'admin_issue_result_statements':'admin_issue_academic_records',{p_applications:ids});
   if(rr.error)failures.push(rr.error.message);else{ok=(rr.data?.issued||[]).length;(rr.data?.skipped||[]).forEach(x=>failures.push(String(x.id).slice(0,8)+': '+x.reason))}
  }else for(const a of batch){try{
    if(action==='delete')await api('admin-delete',{kind:'application',id:a.id,confirm:a.student_id||a.pay_reference||String(a.id).slice(0,8).toUpperCase(),reason:note});
    else if(action==='letter'){
      if(a.admission_decision!=='approved')throw new Error('Admission must be approved first');
      const rr=await sb.rpc('admin_ensure_admission_document',{p_application:a.id});if(rr.error)throw rr.error;
    }else{const rr=await sb.rpc('admin_set_admission',{p_app:a.id,p_decision:action,p_note:note||null});if(rr.error)throw rr.error;}
    ok++;
   }catch(err){failures.push((a.student_id||a.pay_reference||String(a.id).slice(0,8))+': '+(err.message||'Failed'))}
  }
  if(ok)selectedApps.clear();await load();render(true);
  toast(ok+' completed, '+failures.length+' unsuccessful'+(failures.length?'. Open details for reasons.':''),!!failures.length);
  if(failures.length){const m=modal('<h3>Batch action report</h3><p>'+ok+' succeeded; '+failures.length+' failed.</p><ul class="act">'+failures.map(x=>'<li>'+esc(x)+'</li>').join('')+'</ul><button class="btn g" id="closeReport">Close</button>');m.querySelector('#closeReport').onclick=()=>m.remove();}
 }
